#!/usr/bin/env python3
# luxarch:confirm-destructive hook v8 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny irreversible destruction of WORK — deleting is the owner's call.

FLEET-AGENT-CONDUCT-STANDARD #6: removing code, data, a volume or history is a scope decision,
never the agent's on its own authority. A denial costs one message to override; an unwanted
recursive delete or a force push costs work that cannot be recovered.

SCOPED, because the first version denied every recursive delete including scratch/temp cleanup —
and a hook that over-fires is a hook that gets switched off (it blocked routine work within
minutes of shipping). What matters is the TARGET: a path inside a project is real work; the
system temp dir, a scratchpad and a tool cache are not. Each target a command names is judged on
its own, after known variables and `..` are resolved, and every one must be throwaway: one scratch
path does not clear a real one beside it, and a comment that mentions /tmp is not a target. A
literal path that starts in the system temp dir (`/tmp/`, `/var/tmp/`, where the session's
scratchpad lives) and stays there once symlinks are followed is throwaway whatever its segments are
named, `<scratchpad>/verify/migrations/wt` included, when the destruction is the whole command (no
earlier step can turn the path into a link to a checkout) (v7). Anywhere else a source-tree segment
(`src`, `app`, `migrations`, …) is real work. History, volumes and SQL destruction stay in scope
regardless of path.

`git worktree remove --force` deletes a worktree's uncommitted, untracked and ignored files, and
the commits only it holds. It passes only for scratch: run as the whole command, with an absolute
path whose realpath is in the system temp dir (v7). A name that reads as scratch proves nothing,
and every other forced removal is denied.

Commands are read through `_cmdtext.command_text`, so a pattern sitting inside a heredoc or a
quoted literal is DATA and not treated as an execution — the same masking doctrine luxarch's own
line-regex rules use. What the shell runs from inside a command (`bash -c`, `eval`, `$(…)`,
backticks, `find -exec`, a heredoc fed to a shell) is judged as a command of its own
(`_cmdtext.executable_texts`), and programs are also read as argv, so their options are seen
however they are spelled:
  * git: `reset --hard`, a force push (`-f`, `+refspec`, `remote.<name>.push=+…`), deleting a remote
    branch (`--delete`, `:branch`), `clean -f` (or `clean.requireForce=false`), discarding the whole
    tree (`checkout -- .`, `checkout -f`, `restore .`, `switch --discard-changes`), `stash
    drop`/`clear` (the stash is shared by every worktree), `branch -D`/`-M`, `tag -d`, `reflog
    expire`, `update-ref -d`, `worktree remove --force`, `read-tree -u --reset`, `rm -r`
  * `rm` recursive and forced in any spelling, `find … -delete`, `docker compose down/rm -v`
  * DROP, TRUNCATE, `ALTER TABLE … DROP` and a DELETE with no real WHERE, in the SQL a client is
    handed (`psql -c '…'`, `mysql -e`, a heredoc or here-string), SQL comments stripped. Text
    beside the client is not SQL: `truncate -s0 log` and a grep for `DROP TABLE` pass.

PreToolUse(Bash): deny destruction aimed at real work. A tool call this hook cannot read or judge
is denied too.
"""

from __future__ import annotations

import os
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import (  # sibling helper, loaded by path
    GitCall,
    SimpleCommand,
    argv_bodies,
    command_text,
    executable_texts,
    find_targets,
    force_push,
    forced_clean,
    git_calls,
    guarded,
    heredoc_feeds,
    is_abbrev,
    load_event,
    segments,
    simple_commands,
    text_field,
    tool_input,
)

# Dangerous wherever it points — history, data stores, whole schemas.
ALWAYS = (
    (
        re.compile(r"\bgit\s+reset\s+--hard\b"),
        "git reset --hard discards working-tree work",
    ),
    (
        re.compile(r"\bgit\s+push\b[^\n]{0,400}?--force(?!-with-lease)"),
        "force push rewrites pushed history",
    ),
    (
        re.compile(r"\bdocker\s+(?:volume\s+(?:rm|prune)|system\s+prune)\b"),
        "docker volume/system prune destroys data",
    ),
    (
        re.compile(r"(?i)\b(?:DROP\s+(?:TABLE|DATABASE|SCHEMA)|TRUNCATE\s+TABLE)\b"),
        "destructive SQL",
    ),
)

# Recursive delete / force-clean: dangerous only when aimed at real work.
PATH_SCOPED = (
    (
        re.compile(r"\brm\s+(?:-[a-zA-Z]*r[a-zA-Z]*f|-[a-zA-Z]*f[a-zA-Z]*r)\b"),
        "recursive force delete",
    ),
    (
        re.compile(r"\bgit\s+clean\s+-[a-zA-Z]*f"),
        "git clean -f deletes untracked files",
    ),
)

# Throwaway locations — deleting here is housekeeping, not destruction of work.
THROWAWAY = re.compile(
    r"/tmp/|/var/tmp/|\$TMPDIR|\$\{TMPDIR|scratchpad|/\.cache/"
    r"|\bnode_modules\b|__pycache__|\.pytest_cache|\.mypy_cache|\.ruff_cache|\.import_linter_cache"
    r"|\.hypothesis\b|\.venv\b"
    # SwiftPM's and Xcode's build caches, only as a whole path segment: `.build-notes` is not one
    r"|(?:^|[\s/\"'=])(?:\.build|DerivedData)(?=$|[\s/\"';&|)])"
)
# A source-tree path appearing as a target means real work is in range, even alongside a temp path.
REAL_WORK = re.compile(
    r"(?:^|[\s/])(?:src|app|tests|docs|migrations|alembic)(?:/|\s|$)"
)

_SQL_CLIENTS = {"psql", "mysql", "mariadb", "sqlite3", "duckdb", "clickhouse-client"}
# The statement-carrying options of each client; sqlite3/duckdb take SQL after the database.
_SQL_OPTS = {"-c", "--command", "-e", "--execute", "-q", "--query"}
# Literals and comments are not statements. Each pattern runs over ONE statement, so none of them
# can backtrack across a whole payload.
_SQL_NOISE = re.compile(r"'(?:''|[^'])*'|--[^\n]*|/\*.*?\*/", re.S)
_SQL_DROP = re.compile(
    r"(?i)\bDROP\s+(?:MATERIALIZED\s+VIEW|TABLE|DATABASE|SCHEMA|VIEW|INDEX|OWNED|TYPE|FUNCTION"
    r"|SEQUENCE|ROLE|USER|EXTENSION)\b|\bTRUNCATE\b"
)
_SQL_ALTER = re.compile(r"(?i)\bALTER\s+TABLE\b")
_SQL_DROP_WORD = re.compile(r"(?i)\bDROP\b")
_SQL_DELETE = re.compile(r"(?i)\bDELETE\s+FROM\b")
_SQL_REAL_WHERE = re.compile(r"(?i)\bWHERE\s+(?!(?:true|1\s*=\s*1)\b)")


def _sql_destroys(payload: str) -> bool:
    """A statement that drops, truncates, alters away a column, or deletes with no real WHERE."""
    for stmt in _SQL_NOISE.sub(" ", payload).split(";"):
        if _SQL_DROP.search(stmt) or (
            _SQL_ALTER.search(stmt) and _SQL_DROP_WORD.search(stmt)
        ):
            return True
        if _SQL_DELETE.search(stmt) and not _SQL_REAL_WHERE.search(stmt):
            return True
    return False


# A pathspec that names the whole tree.
_WHOLE_TREE = {".", "./", ":/", ":(top)", ":/*", "*", "-A"}


# A literal shell assignment — `SP=/tmp/x/scratchpad`. Only literal values: a `$(...)`/backtick
# value is unknowable here and is deliberately left unexpanded (it then fails the throwaway test,
# which is the safe direction).
_ASSIGN = re.compile(
    r"""^[ \t]*(?:export[ \t]+)?([A-Za-z_][A-Za-z0-9_]*)=(?!\s)((?:"[^"$`]*"|'[^']*'|[^\s'"$`;|&]+))""",
    re.MULTILINE,
)


def _literal_vars(full_cmd: str) -> dict[str, str]:
    """Literal `VAR=value` assignments anywhere in the command."""
    return {m.group(1): m.group(2).strip("\"'") for m in _ASSIGN.finditer(full_cmd)}


def _expand(text: str, vars_: dict[str, str]) -> str:
    """Substitute known literal vars so a segment carries the path it actually deletes."""
    for name, val in vars_.items():
        text = text.replace("${" + name + "}", val).replace("$" + name, val)
    return text


def _resolve_dots(text: str) -> str:
    """Each word holding `..` normalised, so `/tmp/../srv/app` reads as `/srv/app`, not as /tmp."""
    return re.sub(r"\S*\.\.\S*", lambda m: os.path.normpath(m.group(0)), text)


# A path that STARTS in the system temp dir (the session's scratchpad lives there), followed by
# plain path characters only: no quote, brace, glob, `$` or `,` that could name a second path.
_IN_TEMP = re.compile(r"(?:/tmp|/var/tmp)/[\w.+@%=/-]*")
_TEMP_ROOTS = {os.path.realpath("/tmp"), os.path.realpath("/var/tmp")}


def _in_temp(word: str, sole: bool) -> bool:
    """`word` (quotes around it aside) is one path inside the system temp dir, so its segment names
    say nothing about real work (`/tmp/claude-0/…/scratchpad/verify/migrations/wt`). Only when the
    destruction is the whole command (`sole`): an earlier step could make the path a symlink into a
    checkout. A symlink already there is followed: the real path must be in the temp dir too."""
    path = word.strip("\"'")
    if not sole or not _IN_TEMP.fullmatch(path) or ".." in path.split("/"):
        return False  # `..` after a symlink climbs the link's target, not the text's parent
    return _real_in_temp(path)


def _real_in_temp(path: str) -> bool:
    """`path`, every symlink in it followed, is inside the system temp dir."""
    real = os.path.realpath(path)
    return any(real == r or real.startswith(r + "/") for r in _TEMP_ROOTS)


def _real_work(text: str, sole: bool) -> bool:
    """A source-tree segment in `text`, judged word by word: a word that is one path inside the
    temp dir names no source tree, whatever its segments are called."""
    return any(
        REAL_WORK.search(" " + _resolve_dots(w))
        for w in text.split()
        if not _in_temp(w, sole)
    )


def _only_throwaway(
    cmd: str, vars_: dict[str, str] | None = None, sole: bool = False
) -> bool:
    """True when the text of a destruction is confined to throwaway state.

    Conservative on purpose: a source-tree token anywhere in the segment, outside a path that starts
    in the temp dir, makes it count as touching real work. Literal assignments from the whole command
    are resolved first, so `rm -rf "$SP"` is judged by the path `SP` holds."""
    expanded = _expand(cmd, vars_) if vars_ else cmd
    return bool(THROWAWAY.search(_resolve_dots(expanded))) and not _real_work(
        expanded, sole
    )


def _targets_throwaway(targets: list[str], sole: bool = False) -> bool:
    """True when EVERY target is throwaway: one scratch path does not clear a real one beside it."""
    if not targets:
        return False
    for t in targets:
        path = _resolve_dots(t)
        if (
            not THROWAWAY.search(path)
            or (not _in_temp(t, sole) and REAL_WORK.search(" " + path))
            or _through_a_link(t)
        ):
            return False
    return True


# a path the OS cannot resolve: unreadable, or holding a NUL (ValueError)
_UNRESOLVABLE = (OSError, ValueError)


def _through_a_link(target: str) -> bool:
    """A target reached through a symlink deletes in the link's target: `.build/Sources` where
    `.build` links to a checkout, and `rm -rf .build/` or `.build/*` (a trailing slash or a glob
    follow the link itself). Such a target is judged by the path it resolves to, read from the hook's
    working directory; removing a link itself (`rm -rf .build`) removes only the link. A stated
    limit: a relative path is resolved there, not in a directory the command `cd`s into first."""
    path = os.path.expanduser(target.strip("\"'"))
    for var, value in (("PWD", os.getcwd()), ("HOME", os.path.expanduser("~"))):
        path = path.replace(f"${{{var}}}", value)
        path = re.sub(rf"\${var}\b", value.replace("\\", "\\\\"), path)
    head = re.split(r"[*?\[]", path, maxsplit=1)[0]
    if "$" in head or not head:
        return False  # a stated limit: another variable's value is not known here
    follow = head.endswith("/") or head != path
    stem = head.rstrip("/") or "/"
    parent, leaf = os.path.split(os.path.abspath(stem))
    try:
        real = (
            os.path.realpath(stem)
            if follow
            else os.path.join(os.path.realpath(parent), leaf)
        )
    except _UNRESOLVABLE:
        return True
    return real != os.path.abspath(stem) and not THROWAWAY.search(real + "/")


def _worktree_remove_allowed(g: GitCall, sole: bool) -> bool:
    """A forced worktree removal of scratch: the whole command (nothing before it can change the
    target after the check), git not pointed elsewhere, an absolute target as typed (git matches a
    relative name as a suffix of any worktree) whose realpath is in the system temp dir. A name that
    merely reads as scratch (`node_modules-cleanup`) proves nothing, and every other forced removal
    is denied."""
    targets = list(g.positionals[1:])
    if len(targets) != 1 or not sole or _redirected(g):
        return False
    target = targets[0]
    if not os.path.isabs(target) or ".." in target.split("/"):
        return False
    return _real_in_temp(target)


_GIT_PLACE_ENV = {"GIT_DIR", "GIT_WORK_TREE", "GIT_COMMON_DIR", "GIT_INDEX_FILE"}
_GIT_PLACE_OPTION = re.compile(r"(?:^|\s)--(?:git-dir|work-tree)\b")


def _redirected(g: GitCall) -> bool:
    """git is pointed at a repository or work tree other than where it runs: what it deletes is
    then not the path the command shows."""
    return (
        any(k in _GIT_PLACE_ENV for k, _ in g.env)
        or bool(_GIT_PLACE_OPTION.search(g.raw))
        or any(k in ("core.worktree", "core.bare") for k, _ in g.config)
    )


def _operands(argv: tuple[str, ...]) -> list[str]:
    """The non-option words of a command; everything after `--` counts."""
    out: list[str] = []
    after = False
    for w in argv[1:]:
        if after or not w.startswith("-") or w == "-":
            out.append(w)
        elif w == "--":
            after = True
    return out


def _flag(flags: tuple[str, ...], short: str, long: str, shortest: int) -> bool:
    return short in flags or any(is_abbrev(f, long, shortest) for f in flags)


def _git_destroys(g: GitCall, sole: bool = False) -> str | None:
    flags, words = g.flags, list(g.positionals)
    sole = sole and not _redirected(g)
    if g.sub == "reset" and any(is_abbrev(f, "--hard", 3) for f in flags):
        return "git reset --hard discards working-tree work"
    if force_push(g):
        return "force push rewrites pushed history"
    if g.sub == "push" and (
        _flag(flags, "-d", "--delete", 4) or any(w.startswith(":") for w in words[1:])
    ):
        return "deleting a remote branch destroys pushed history"
    if forced_clean(g) and not _targets_throwaway(words or [g.cwd or "."], sole):
        return "git clean -f deletes untracked files"
    if g.sub == "checkout" and (
        _flag(flags, "-f", "--force", 4) or any(w in _WHOLE_TREE for w in words)
    ):
        return "git checkout of the whole tree discards uncommitted work"
    if g.sub == "switch" and (
        _flag(flags, "-f", "--force", 7)
        or any(is_abbrev(f, "--discard-changes", 4) for f in flags)
    ):
        return "git switch --discard-changes throws away uncommitted work"
    staged_only = _flag(flags, "-S", "--staged", 4) and not _flag(
        flags, "-W", "--worktree", 4
    )
    if g.sub == "restore" and any(w in _WHOLE_TREE for w in words) and not staged_only:
        return "git restore of the whole tree discards uncommitted work"
    if g.sub == "stash" and words[:1] in (["drop"], ["clear"]):
        return "git stash drop/clear destroys stashed work (the stash is shared by every worktree)"
    if g.sub == "branch" and (
        "-D" in flags
        or "-M" in flags
        or (_flag(flags, "-d", "--delete", 5) and _flag(flags, "-f", "--force", 4))
    ):
        return "git branch -D/-M deletes or overwrites a branch whether or not it is merged"
    if g.sub == "reflog" and words[:1] == ["expire"]:
        return "git reflog expire drops the history that recovers lost commits"
    if g.sub == "update-ref" and "-d" in flags:
        return "git update-ref -d deletes a ref"
    if g.sub == "tag" and _flag(flags, "-d", "--delete", 5):
        return "git tag -d deletes a tag"
    if (
        g.sub == "worktree"
        and words[:1] == ["remove"]
        and _flag(flags, "-f", "--force", 4)
        and not _worktree_remove_allowed(g, sole)
    ):
        return (
            "git worktree remove --force deletes a worktree holding work (it passes on its own, "
            "with an absolute path, only for a worktree in the system temp dir)"
        )
    if g.sub == "read-tree" and "-u" in flags and "--reset" in flags:
        return "git read-tree -u --reset overwrites the working tree"
    if (
        g.sub == "rm"
        and "-r" in flags
        and "--cached" not in flags
        and not _targets_throwaway(words, sole)
    ):
        return "git rm -r deletes tracked work"
    return None


def _compose_args(argv: tuple[str, ...]) -> list[str] | None:
    """The arguments after `docker compose` / `docker-compose`, or None for another program."""
    base = os.path.basename(argv[0])
    if base == "docker-compose":
        return list(argv[1:])
    if base == "docker" and "compose" in argv:
        return list(argv[argv.index("compose") + 1 :])
    return None


def _drops_volumes(args: list[str], sub: str) -> bool:
    if sub not in args:
        return False
    after = args[args.index(sub) + 1 :]
    return "--volumes" in after or any(
        w.startswith("-") and not w.startswith("--") and "v" in w for w in after
    )


def _program_destroys(sc: SimpleCommand, sole: bool = False) -> str | None:
    argv = sc.argv
    base = os.path.basename(argv[0])
    if base == "rm":
        short = "".join(
            w[1:] for w in argv[1:] if w.startswith("-") and not w.startswith("--")
        )
        recursive = "r" in short or "R" in short or "--recursive" in argv
        forced = "f" in short or "--force" in argv
        if recursive and forced and not _targets_throwaway(_operands(argv), sole):
            return "recursive force delete"
    if (
        base == "find"
        and "-delete" in argv
        and not _targets_throwaway(
            find_targets(argv),
            sole and not any(w in ("-L", "-H", "-follow") for w in argv),
        )
    ):
        return "find -delete removes every file it matches"
    compose = _compose_args(argv)
    if compose is not None and (
        _drops_volumes(compose, "down") or _drops_volumes(compose, "rm")
    ):
        return "docker compose down/rm -v destroys the stack's volumes (its data)"
    return None


def _sql_payloads(text: str) -> list[str]:
    """The SQL each client in `text` is handed: its statement option, the SQL after an sqlite3 or
    duckdb database, and a heredoc or here-string it reads. Text around the client is not SQL."""
    out: list[str] = []
    for sc in simple_commands(text):
        idx = next(
            (k for k, w in enumerate(sc.argv) if os.path.basename(w) in _SQL_CLIENTS),
            None,
        )
        if idx is None:
            continue
        args = sc.argv[idx + 1 :]
        for k, w in enumerate(args):
            if w in _SQL_OPTS and k + 1 < len(args):
                out.append(args[k + 1])
            elif w.startswith(("--command=", "--execute=", "--query=")):
                out.append(w.split("=", 1)[1])
        if os.path.basename(sc.argv[idx]) in ("sqlite3", "duckdb"):
            out.extend(_operands(("", *args))[1:])
        out.extend(argv_bodies(sc))
    for body, runner in heredoc_feeds(text):
        if any(os.path.basename(w) in _SQL_CLIENTS for w in runner):
            out.append(body)
    return out


def _deny(why: str) -> int:
    print(
        f"DENIED: {why}.\n"
        "Deleting/destroying is the owner's call (conduct standard #6) — verification is not "
        "authorization. Say WHAT you want to remove, the evidence, and whether it is superseded / "
        "never-wired / orphaned, then let the owner rule. (Cleanup confined to /tmp, a scratchpad "
        "or a tool cache is not blocked.)",
        file=sys.stderr,
    )
    return 2


def main() -> int:
    ev = load_event()
    if ev.get("tool_name") != "Bash":
        return 0
    raw = text_field(tool_input(ev), "command")
    vars_ = _literal_vars(raw)
    commands = simple_commands(raw)
    # the destruction is the whole command: no earlier step can change what its target is
    sole = len(commands) == 1 and len(executable_texts(raw)) == 1
    for text in executable_texts(raw):
        masked = command_text(text)
        for rx, why in ALWAYS:
            if rx.search(masked):
                return _deny(why)
        # Judge each SEGMENT on its own, and ask each question of the right text: the VERB on
        # masked text (so a quoted example is not read as an execution), the TARGET on raw text
        # (so a quoted path is still visible).
        for seg_masked, seg_raw in segments(text):
            for rx, why in PATH_SCOPED:
                if rx.search(seg_masked) and not _only_throwaway(seg_raw, vars_, sole):
                    return _deny(why)
        if any(_sql_destroys(p) for p in _sql_payloads(text)):
            return _deny("destructive SQL")
    found = next((w for g in git_calls(raw) if (w := _git_destroys(g, sole))), None)
    found = found or next(
        (w for sc in commands if (w := _program_destroys(sc, sole))), None
    )
    return _deny(found) if found else 0


sys.exit(guarded(main, "confirm-destructive"))
